import '../setup-filesystem-isolation.js';
import assert from 'node:assert/strict';
import { Database } from 'bun:sqlite';
import { join } from 'node:path';
import { initDatabase,getDb,closeDatabase } from '../../src/db/connection.js';
import { ensureBudgetWork,saveBudgetCap } from '../../src/db/budget-limits.js';
import { getStoreDir } from '../../src/core/config.js';
import { admitBudgetRequest,admitBudgetRequestDispatch } from '../../src/budget/request-reservation-admission.js';
import { getBudgetRequest } from '../../src/db/budget-request-reservations.js';
import { performance } from 'node:perf_hooks';
import { renameSync } from 'node:fs';
assert.equal(process.env.PICLAW_DB_IN_MEMORY,'0');initDatabase();
assert.equal((getDb().query('PRAGMA busy_timeout').get() as {timeout:number}).timeout,0);
ensureBudgetWork({id:'disk-parent',chatJid:'web:disk',executionKind:'interactive'});
saveBudgetCap({scope:'task',metric:'api_usd_micros',amount:100,workId:'disk-parent'});
const binding={id:'disk-request',workId:'disk-parent',chatJid:'web:disk',providerId:'fixture',modelId:'fixture',accountRef:'fixture',amountMicros:60};
const path=join(getStoreDir(),'messages.db'),blocker=new Database(path);blocker.exec('BEGIN IMMEDIATE');
let released=false;const start=performance.now();let timerMs=0;
const timer=new Promise<void>(resolve=>setTimeout(()=>{timerMs=performance.now()-start;resolve();},10));
const pending=admitBudgetRequest(binding,{signal:new AbortController().signal,authorise(){}}).then(row=>{assert(released);return row;});
await timer;assert.equal(getBudgetRequest(binding.id),null);blocker.exec('ROLLBACK');blocker.close();released=true;
assert.equal((await pending).state,'reserved');
assert.equal((getDb().query('PRAGMA busy_timeout').get() as {timeout:number}).timeout,0);
const second=new Database(path);second.exec('BEGIN IMMEDIATE');let valid=true;
const revoke=admitBudgetRequestDispatch(binding,{signal:new AbortController().signal,authorise(){if(!valid)throw Error('revoked');}}).then(()=>false,()=>true);
await Bun.sleep(0);valid=false;second.exec('ROLLBACK');second.close();assert.equal(await revoke,true);assert.equal(getBudgetRequest(binding.id)?.state,'reserved');
const aborter=new AbortController();aborter.abort(Error('cancelled'));assert.equal(await admitBudgetRequest({...binding,id:'cancelled'}, {signal:aborter.signal,authorise(){}}).then(()=>false,()=>true),true);assert.equal(getBudgetRequest('cancelled'),null);
const third=new Database(path);third.exec('BEGIN IMMEDIATE');
const replacement=admitBudgetRequestDispatch(binding,{signal:new AbortController().signal,authorise(){}}).then(()=>null,error=>error);
await Bun.sleep(0);const displaced=`${path}.displaced`;renameSync(path,displaced);await Bun.write(path,'replacement-inode');third.exec('ROLLBACK');third.close();
assert.match(String(await replacement),/database file changed/);assert.equal(getBudgetRequest(binding.id)?.state,'reserved');
await closeDatabase();console.log(JSON.stringify({kind:'budget-request-admission-disk',timerMs,reservedAfterRelease:true,revokedDispatchDenied:true,cancelledNoHold:true,busyTimeoutRestored:true,replacedDatabaseDenied:true,scope:'actual reservation admission with owned WAL writer; no provider/auth/model execution'}));
